export const FALLBACK_ICON = 'ECommerce/Tag';

// Icon key for an emoji (or an icon key passed through), with a fallback so
// an unknown emoji never shows up as an emoji.
export const iconKeyFor = (value) => {
  if (!value) return FALLBACK_ICON;
  if (ICON_SVG[value]) return value;
  const clean = String(value).trim();
  return EMOJI_ICON[clean] || EMOJI_ICON[clean.replace(/\uFE0F/g, '')] || EMOJI_ICON[clean + '\uFE0F'] || FALLBACK_ICON;
};

